import path from "node:path";
import type { PgDatabase, PgQueryResultHKT } from "drizzle-orm/pg-core";
import * as schema from "./schema";

/** A Drizzle database over either node-postgres or PGlite. Both speak the same PostgreSQL dialect. */
export type Db = PgDatabase<PgQueryResultHKT, typeof schema>;

export interface ConnectOptions {
  /** postgres:// URL. When absent, PGlite is used. */
  url?: string;
  /** PGlite data directory, or "memory" for an in-memory database (tests). */
  pgliteDir?: string;
  migrate?: boolean;
}

/** Migrations are generated by drizzle-kit into ./drizzle at the repository root. */
function migrationsFolder(): string {
  return path.join(process.cwd(), "drizzle");
}

export async function createDatabase(opts: ConnectOptions): Promise<Db> {
  if (opts.url) {
    const { Pool } = await import("pg");
    const { drizzle } = await import("drizzle-orm/node-postgres");
    const pool = new Pool({ connectionString: opts.url, max: 10 });
    const db = drizzle(pool, { schema }) as unknown as Db;
    if (opts.migrate) {
      const { migrate } = await import("drizzle-orm/node-postgres/migrator");
      await migrate(db as never, { migrationsFolder: migrationsFolder() });
    }
    return db;
  }
  const { PGlite } = await import("@electric-sql/pglite");
  const { drizzle } = await import("drizzle-orm/pglite");
  const dir = opts.pgliteDir ?? "memory";
  const client = dir === "memory" ? new PGlite() : new PGlite(dir);
  const db = drizzle(client, { schema }) as unknown as Db;
  if (opts.migrate) {
    const { migrate } = await import("drizzle-orm/pglite/migrator");
    await migrate(db as never, { migrationsFolder: migrationsFolder() });
  }
  return db;
}
